def transform_demo(grid):
    h,w=len(grid),len(grid[0])
    seed=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    r0=min(r for r,c in seed); c0=min(c for r,c in seed)
    motif={(r-r0,c-c0) for r,c in seed}
    out=[row[:] for row in grid]
    mh=max(r for r,c in motif); mw=max(c for r,c in motif)
    for r in range(h-mh):
        for c in range(w-mw):
            pts=[(r+dr,c+dc) for dr,dc in motif]
            if all(grid[rr][cc]==0 for rr,cc in pts):
                for rr,cc in pts: out[rr][cc]=8
    return out
